 P=ROOT/'research/experiments/20261126T175734Z';rd=lambda p:json.loads(p.read_text());gz=lambda p:json.loads(gzip.decompress(p.read_bytes()));ms=lambda s:int(datetime.fromisoformat(s.replace('Z','+00:00')).timestamp()*1000);w=rd(R/'account_windows.json')['SMA'];begin,cut=ms(w['start_utc']),ms(w['cutoff_utc']);assert w['expected_daily_events_utc']==['2026-11-26T00:01:00Z'] and cut-begin==7200000
